import {preset,validate,inputFromRecord} from './trail-bike.js'
import {rigLandmarks} from './bike-geometry.js';
import {geometryFor} from './linkage.js';
const $=id=>document.getElementById(id),form=$('setup'),keys={bike:'bike',rider:'bike',mass:'bike',riderMass:'bike',velocityX:'motion',clearance:'motion',forkCompression:'motion',omega:'motion',duration:'motion',nodes:'wheel',dt:'motion'};let input=normalized(preset('bump')),applied,worker,revision=0,dirty=true,playing=false,index=0,lastStamp=0,elapsed=0,animation=0;
const inputs=r=>r.scenario;
function normalized(a){const {bike,wheel,motion,profile,assembly}=validate(a);return {bike,wheel,motion,profile,assembly};}
function pause(){playing=false;cancelAnimationFrame(animation);animation=0;$('play').textContent='Play';lastStamp=0;}
function controls(){const ok=!dirty&&!!applied?.frames.length;for(const id of ['play','reset','step','scrub'])$(id).disabled=!ok;$('save').disabled=dirty||!applied;}
function stop(){revision++;worker?.terminate();worker=null;$('cancel').disabled=true;pause();}
function edits(){stop();dirty=true;controls();$('status').textContent='UNAPPLIED EDITS';}
function reject(error){edits();$('status').textContent='INPUT REJECTED';$('error').textContent=error.message;}
function fill(a){$('example').value=['bump','flat','flight','limit'].find(name=>JSON.stringify(normalized(preset(name,a.bike.bike)))===JSON.stringify(a))??'authored';const dt=form.elements.dt;dt.querySelectorAll('[data-authored]').forEach(o=>o.remove());if(!Array.from(dt.options).some(o=>o.value===String(a.motion.dt))){const o=new Option((a.motion.dt*1000)+' ms (authored)',String(a.motion.dt));o.dataset.authored='true';dt.add(o);}for(const [key,section] of Object.entries(keys))form.elements[key].value=String(a[section][key]);$('setupText').value=JSON.stringify(a,null,2);}
function calculate(a){input=structuredClone(a);stop();const ticket=revision;dirty=true;controls();$('status').textContent='CALCULATING';$('error').textContent='';$('cancel').disabled=false;worker=new Worker(new URL('./trail-bike-worker.js',import.meta.url),{type:'module'});worker.onerror=()=>{if(ticket===revision)reject(Error('Connected-bike worker failed. Apply again to retry.'));};worker.onmessage=e=>{if(ticket!==revision)return;if(e.data.error){reject(Error(e.data.error));return;}applied=e.data.result;input=inputs(applied);stop();dirty=false;index=0;elapsed=0;fill(input);$('scrub').max=Math.max(0,applied.frames.length-1);controls();render();};worker.postMessage(a);}
function render(){if(!applied)return;const r=applied,f=r.frames[index];$('status').textContent=r.status.toUpperCase().replaceAll('-',' ');$('scrub').value=index;$('time').textContent=f?f.time.toFixed(4)+' s':'—';$('force').textContent=f?f.wheels.map(w=>w.ground[1].toFixed(0)).join(' / ')+' N':'—';$('travel').textContent=f?(1000*f.fork).toFixed(1)+' / '+(1000*f.shock).toFixed(1)+' mm':'—';$('reason').textContent=r.termination?'Stopped: '+r.termination.reason+' at '+r.termination.time.toFixed(6)+' s. '+(r.status==='terminated'?'The attempted step was rejected; this is the last accepted state.':'No motion is admitted.'):'Run complete within the declared model limits.';$('summary').textContent=r.summary?'Peak '+r.summary.peakForce.toFixed(0)+' N · overlap '+(1000*r.summary.peakPenetration).toFixed(3)+' mm':'';$('ledger').textContent=f?'Energy '+f.energy.toFixed(3)+' J · native and buffer damping loss '+f.dampingLoss.toFixed(3)+' J · signed constraint work '+f.constraintWork.toFixed(3)+' J · balance residual '+f.residual.toExponential(2)+' J. Stationary ground supplies no external work; soft-contact work includes storage and release.':'';$('loads').textContent=f?'Front / rear bearing force '+f.wheels.map(w=>Math.hypot(w.bearing[0],w.bearing[1]).toFixed(1)).join(' / ')+' N · free-root residual '+Math.max(...f.root.map(Math.abs)).toExponential(2)+' (N, N m). Guided-rider reaction '+Math.hypot(f.guide[0],f.guide[1]).toFixed(1)+' N.':'';$('assemblyStatus').textContent=r.assessment.status==='incompatible'?'Assembly declaration rejected.':(r.assessment.status==='unknown'?'Assembly evidence unknown. ':'Within declared service limits. ')+(r.massBudget?'Total mass '+r.massBudget.total.toFixed(1)+' kg; frame and rider '+r.massBudget.frameAndRider+' kg, plus carriers, hubs and casing. ':'')+'Illustrative values; no tyre or component survival certification.';draw();history();}
function canvas(id){const el=$(id),w=el.clientWidth,h=el.clientHeight;if(w<40||h<40)return null;const dpr=devicePixelRatio||1;el.width=Math.round(w*dpr);el.height=Math.round(h*dpr);const c=el.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);return {c,w,h};}
function arrow(c,x,z,fx,fz,color,scale){const dx=fx*scale,dz=-fz*scale,len=Math.hypot(dx,dz);if(len<.1)return;c.strokeStyle=color;c.fillStyle=color;c.lineWidth=1.4;c.beginPath();c.moveTo(x,z);c.lineTo(x+dx,z+dz);c.stroke();const ux=dx/len,uz=dz/len;c.beginPath();c.moveTo(x+dx,z+dz);c.lineTo(x+dx-6*ux+3*uz,z+dz-6*uz-3*ux);c.lineTo(x+dx-6*ux-3*uz,z+dz-6*uz+3*ux);c.closePath();c.fill();}
function draw(){if(!applied)return;const view=canvas('rig');if(!view)return;const {c,w,h}=view,r=applied,a=r.scenario,f=r.frames[index];c.fillStyle='#9aabb7';c.font='11px system-ui';c.fillText('x →  z ↑ · equal scale · frictionless · passive rider guide',10,16);if(!f){c.fillText('No accepted state to display.',15,60);return;}
 const frames=r.frames,xs=frames.flatMap(f=>f.wheels.map(w=>w.hub[0])),zs=frames.flatMap(f=>[f.rider[1]+.12,...f.wheels.map(w=>w.hub[1]+.36)]),xmin=Math.min(...xs)-.45,xmax=Math.max(...xs)+.45,zmin=Math.min(...r.scenario.profile.points.map(p=>p[1]))-.08,zmax=Math.max(...zs)+.1,scale=Math.min((w-30)/(xmax-xmin),(h-42)/(zmax-zmin)),x=v=>w/2+(v-(xmin+xmax)/2)*scale,z=v=>h/2-(v-(zmin+zmax)/2)*scale;
 const path=(points,color,width=2,close=false)=>{c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach((q,i)=>i?c.lineTo(x(q[0]),z(q[1])):c.moveTo(x(q[0]),z(q[1])));if(close)c.closePath();c.stroke();};c.save();c.beginPath();c.rect(6,24,w-12,h-32);c.clip();path(a.profile.points,'#83979d');
 const points=rigLandmarks({bike:a.bike.bike,pitch:f.frame[2],heave:f.frame[1],fork:f.fork,rearAngle:f.rearAngle,geometry:geometryFor(a.bike)});for(const q of Object.values(points))q[0]+=f.frame[0];const b=points;
 path([b.bb,b.seat,b.headTop,b.headBottom,b.bb],'#e5edf2',3);path([b.headBottom,b.front],'#84c8ff',4);path(a.bike.bike==='full'?[b.bb,b.pivot,b.rear,b.bb]:[b.seat,b.rear,b.bb],'#e5edf2',3);if(a.bike.bike==='full')path([b.shockFrame,b.shockArm],'#f2b373',5);
 c.setLineDash([4,3]);path([[f.frame[0],f.frame[1]],f.rider],'#f2b373',2);c.setLineDash([]);c.fillStyle='#f2b373';c.beginPath();c.arc(x(f.rider[0]),z(f.rider[1]),7,0,2*Math.PI);c.fill();
 for(const wheel of f.wheels){c.lineJoin='round';c.lineCap='round';path(wheel.nodes,'#70e2ce',2*a.wheel.skin*scale,true);c.strokeStyle='#c2a3ff';c.lineWidth=1.5;c.beginPath();c.arc(x(wheel.hub[0]),z(wheel.hub[1]),a.wheel.rimRadius*scale,0,2*Math.PI);c.stroke();path([[wheel.hub[0],wheel.hub[1]],[wheel.hub[0]+a.wheel.rimRadius*Math.cos(wheel.hub[2]),wheel.hub[1]-a.wheel.rimRadius*Math.sin(wheel.hub[2])]],'#c2a3ff',1);arrow(c,x(wheel.hub[0]),z(wheel.hub[1]),wheel.ground[0],wheel.ground[1],'#84c8ff',.00025*scale);}
 for(const contact of f.contacts)arrow(c,x(contact.point[0]),z(contact.point[1]),...contact.force,'#f2b373',.00025*scale);c.restore();}
function history(){if(!applied)return;const view=canvas('history');if(!view)return;const {c,w,h}=view,frames=applied.frames;if(!frames.length)return;const xmax=frames.at(-1).time||1,tracks=[{value:a=>a.wheels[0].ground[1],label:'Front ground force / N',color:'#84c8ff'},{value:a=>a.wheels[1].ground[1],label:'Rear ground force / N',color:'#f2b373'}];c.font='11px system-ui';tracks.forEach((track,j)=>{const top=j*h/2+22,bottom=(j+1)*h/2-12,vals=frames.map(track.value),lo=Math.min(0,...vals),hi=Math.max(1e-8,...vals),x=t=>42+(w-54)*t/xmax,z=v=>bottom-(bottom-top)*(v-lo)/(hi-lo);c.fillStyle='#9aabb7';c.fillText(track.label,8,top-7);c.fillText(hi.toPrecision(3),4,top+8);c.strokeStyle='#344654';c.beginPath();c.moveTo(42,z(0));c.lineTo(w-12,z(0));c.stroke();c.strokeStyle=track.color;c.beginPath();frames.forEach((a,i)=>i?c.lineTo(x(a.time),z(track.value(a))):c.moveTo(x(a.time),z(track.value(a))));c.stroke();c.strokeStyle='#c2a3ff';c.beginPath();c.moveTo(x(frames[index].time),top);c.lineTo(x(frames[index].time),bottom);c.stroke();});}
form.oninput=edits;form.onsubmit=e=>{e.preventDefault();try{const a=structuredClone(input);for(const [key,section] of Object.entries(keys))a[section][key]=['bike','rider'].includes(key)?form.elements[key].value:form.elements[key].value.trim()?Number(form.elements[key].value):NaN;calculate(normalized(a));}catch(error){reject(error);}};$('setupText').oninput=edits;$('applyJson').onclick=()=>{try{const text=$('setupText').value;if(new TextEncoder().encode(text).length>8*1024*1024)throw Error('Input exceeds 8 MiB.');calculate(normalized(JSON.parse(text)));}catch(error){reject(error);}};
$('example').onchange=()=>{const a=normalized(preset($('example').value,form.elements.bike.value));fill(a);calculate(a);};$('restore').onclick=()=>{if(!applied)return;stop();input=inputs(applied);dirty=false;fill(input);$('error').textContent='';controls();render();};$('cancel').onclick=()=>{edits();$('status').textContent='CANCELLED';};$('scrub').oninput=()=>{pause();index=Number($('scrub').value);elapsed=applied.frames[index].time;render();};$('reset').onclick=()=>{pause();index=0;elapsed=0;render();};$('step').onclick=()=>{pause();index=Math.min(index+1,applied.frames.length-1);elapsed=applied.frames[index].time;render();};$('play').onclick=()=>{if(playing){pause();return;}if(index===applied.frames.length-1){index=0;elapsed=0;}playing=true;$('play').textContent='Pause';lastStamp=0;animation=requestAnimationFrame(tick);};
function tick(stamp){if(!playing||dirty)return;if(lastStamp)elapsed+=Math.min((stamp-lastStamp)/1000,.05);lastStamp=stamp;while(index<applied.frames.length-1&&applied.frames[index+1].time<=elapsed)index++;render();if(index===applied.frames.length-1)pause();else animation=requestAnimationFrame(tick);}
$('load').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;edits();const ticket=revision;try{if(file.size>8*1024*1024)throw Error('Record exceeds 8 MiB.');const text=await file.text();if(ticket!==revision)return;calculate(inputFromRecord(JSON.parse(text.replace(/^\uFEFF/,''))));}catch(error){if(ticket===revision)reject(error);}};$('save').onclick=()=>{if(dirty||!applied)return;const url=URL.createObjectURL(new Blob([JSON.stringify(applied)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='bikelab-trail-bike.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(()=>{draw();history();}).observe($('rig'));window.addEventListener('resize',()=>{draw();history();});window.addEventListener('pagehide',()=>{if(worker)edits();pause();});fill(input);calculate(input);
